package com.example.discovery.consumer.api;import com.example.discovery.consumer.model.ErrorResponse;import com.example.discovery.consumer.service.ServiceUnavailableException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ServiceUnavailableException.class) ResponseEntity<ErrorResponse> unavailable(ServiceUnavailableException ex){return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(new ErrorResponse("SERVICE_UNAVAILABLE",ex.getMessage()));}}
